 w.THREE={...THREE,WebGLRenderer,GLTFLoader};w.eval(readFileSync(new URL('../../race-smoothing.js',import.meta.url),'utf8'));w.eval(readFileSync(new URL('../../qualifying-colors.js',import.meta.url),'utf8'));w.eval(readFileSync(new URL('../../circuits.js',import.meta.url),'utf8'));
 const instrumented=script.replace('requestAnimationFrame(frame);\n})();',"window.__state=function(){return {x:pos.x,z:pos.z,cameraX:camera.position.x,cameraZ:camera.position.z,speed:v,steer:steer}};window.__practiceSector=function(best,time){multiplayer=null;qualInvalid=false;qualSector=0;qualLastSplit=0;qualSectorBest=[best,null,null,null];qualSectorTimes=[];qualSectorColors=[];lapStart=0;raceTime=time;recordQualSector();return qualSectorColors[0]};window.__practiceLap=function(best,time){multiplayer=null;state='racing';mode='qualifying';qualFlying=true;qualInvalid=false;qualSector=3;total=N;qualLine=0;v=20;lapStart=0;raceTime=time;qualBest=best;qualSectorBest=[null,null,null,null];qualSectorTimes=[];qualAttempts=0;qualifyingProgress(N-1);return {label:$('qualMessage').textContent,time:$('qualTime').textContent,classes:$('qualBanner').className}};window.__physicsProbe=function(){multiplayer=null;state='racing';mode='race';gridSpot(N-9);v=.1;steer=0;keys={Space:true};for(var i=0;i<60;i++)physics(1/60);var result=v;keys={};return result};window.__start=startBtn;requestAnimationFrame(frame);\n})();");assert.notEqual(instrumented,script);w.eval(instrumented);await new Promise(r=>setTimeout(r,10));assert.equal(w.__start.disabled,false);
