  for(const r of roads){const p=r.geometry.getAttribute('position'),sphere=r.geometry.boundingSphere;for(let i=0;i<p.count;i++)assert.ok(new THREE.Vector3(p.getX(i),p.getY(i),p.getZ(i)).distanceTo(sphere.center)<=sphere.radius+.001,`${id} road culling bound`)}
