test('desktop practice culls complete circuit sections and adapts high-DPI rendering without changing models',async t=>{
 const html=readFileSync(new URL('../../index.html',import.meta.url),'utf8'),script=[...html.matchAll(/<script(?:\s[^>]*)?>([\s\S]*?)<\/script>/g)].map(x=>x[1]).find(s=>s.includes('function frame(now)'));
 const dom=new JSDOM(html,{runScripts:'outside-only',url:'http://game.test/'}),w=dom.window;t.after(()=>w.close());let now=1000;Object.defineProperty(w.performance,'now',{value:()=>now});Object.defineProperty(w,'devicePixelRatio',{value:2});
 const ctx=new Proxy({createLinearGradient:()=>({addColorStop(){}}),createRadialGradient:()=>({addColorStop(){}}),measureText:()=>({width:10})},{get:(o,k)=>k in o?o[k]:(()=>{}),set:(o,k,v)=>(o[k]=v,true)});w.HTMLCanvasElement.prototype.getContext=()=>ctx;w.matchMedia=()=>({matches:false,addListener(){},removeListener(){}});w.requestAnimationFrame=cb=>{w.__frame=cb};w.fetch=async()=>({ok:false});class WebGLRenderer{constructor(){this.shadowMap={};this.capabilities={getMaxAnisotropy:()=>1}}setPixelRatio(v){this.ratio=v}setSize(){}render(){}}class GLTFLoader{parse(_,__,___,error){error()}}w.THREE={...THREE,WebGLRenderer,GLTFLoader};
 for(const name of ['race-smoothing.js','qualifying-colors.js','circuits.js','practice-ai.js'])w.eval(readFileSync(new URL('../../'+name,import.meta.url),'utf8'));w.eval(script.replace('requestAnimationFrame(frame);\n})();','window.__quality=()=>({scene:scene,camera:camera,renderer:renderer,N:N});requestAnimationFrame(frame);\n})();'));await new Promise(r=>setTimeout(r,10));
 const {scene,camera,renderer,N}=w.__quality(),ribbons=scene.children.filter(o=>o.userData.trackRibbon),barriers=scene.children.filter(o=>o.userData.trackBarrier);assert.ok(ribbons.length>5&&barriers.length>1);assert.equal(ribbons.reduce((n,o)=>n+o.geometry.index.count,0),5*N*6);assert.equal(barriers.reduce((n,o)=>n+o.count,0),N*2);
 for(const section of barriers){assert.equal(section.frustumCulled,true);const matrix=new THREE.Matrix4(),point=new THREE.Vector3();for(let i=0;i<section.count;i++){section.getMatrixAt(i,matrix);point.setFromMatrixPosition(matrix);assert.ok(point.length()+2<section.geometry.boundingSphere.radius)}}
 w.document.getElementById('start').click();w.document.getElementById('practiceButton').click();w.document.getElementById('raceMode').click();w.document.querySelector('[data-circuit=sepang]').click();now+=16;w.__frame(now);assert.equal(renderer.shadowMap.autoUpdate,true,'solo practice shadows update every frame');now+=16;w.__frame(now);assert.equal(renderer.shadowMap.autoUpdate,true);
 camera.updateMatrixWorld();const frustum=new THREE.Frustum().setFromProjectionMatrix(new THREE.Matrix4().multiplyMatrices(camera.projectionMatrix,camera.matrixWorldInverse));let visible=0;for(const section of barriers){section.updateMatrixWorld();if(frustum.intersectsObject(section))visible++}assert.ok(visible<barriers.length,'off-screen barriers are excluded from drawing');
 for(let i=0;i<70;i++){now+=40;w.__frame(now)}assert.ok(renderer.ratio<2&&renderer.ratio>=1,'sustained slow frames reduce excess high-DPI pixels');const slowRatio=renderer.ratio;for(let i=0;i<400;i++){now+=16;w.__frame(now)}assert.ok(renderer.ratio>slowRatio&&renderer.ratio<=2,'resolution recovers gradually');w.document.getElementById('returnMenu').click();now+=16;w.__frame(now);assert.equal(renderer.shadowMap.autoUpdate,true);
 w.document.getElementById('start').click();w.document.getElementById('practiceButton').click();w.document.getElementById('raceMode').click();w.document.getElementById('practiceAI').checked=true;w.document.querySelector('[data-circuit=sepang]').click();now+=16;w.__frame(now);assert.equal(renderer.shadowMap.autoUpdate,true,'AI practice shadows also update every frame');
});
